import React, { useState, useEffect, useRef } from 'react'
import { chat, getProducts, getProduct } from './api';

export default function App() {
  const [sessionId, setSessionId] = useState(null)
  const [messages, setMessages] = useState([])
  const [input, setInput] = useState('')
  const [suggestions, setSuggestions] = useState([])
  const [loading, setLoading] = useState(false) // Typing indicator
  const chatRef = useRef(null)

  useEffect(() => {
    // Initial greeting
    (async () => {
      try {
        setLoading(true)
        const res = await chat(null, 'hi')
        setSessionId(res.session_id)
        addBotMessage(res.reply)
      } catch (err) {
        addBotMessage('Sorry the chatbot is currently unavailable.')
      } finally {
        setLoading(false)
      }
    })()
  }, [])

  function addUserMessage(txt) {
    setMessages(m => [...m, { role: 'user', text: txt }])
  }

  function addBotMessage(txt, product = null) {
    setMessages(m => [...m, { role: 'bot', text: txt, product }])
  }

  async function handleSend(msgText = null) {
    const msg = msgText || input.trim()
    if (!msg) return
    addUserMessage(msg)
    setInput('')
    setLoading(true)

    try {
      const res = await chat(sessionId, msg)
      setSessionId(res.session_id)
      addBotMessage(res.reply, res.product)
      setSuggestions(res.suggestions || [])
    } catch (err) {
      addBotMessage('Sorry I could not reach the server. Please try again later.')
    } finally {
      setLoading(false)
      // Scroll to bottom
      setTimeout(() => {
        if (chatRef.current) chatRef.current.scrollTop = chatRef.current.scrollHeight
      }, 50)
    }
  }

  return (
    <div className="app">
      <div className="header">
        <h2>Lato Chatbot</h2>
      </div>

      <div className="chatbox" ref={chatRef}>
        {messages.map((m, i) => (
          <div key={i} className={m.role === 'user' ? 'user' : 'bot'}>
            <div
              style={{
                display: 'inline-block',
                background: m.role === 'user' ? '#d1f2f0' : '#f1f5f9',
                padding: 10,
                borderRadius: 8,
              }}
            >
              {m.text.split('\n').map((line, idx) => (
                <div key={idx}>{line}</div>
              ))}

              {m.product && (
                <div
                  className="productCard"
                  style={{ marginTop: 8, cursor: 'pointer' }}
                  onClick={() => handleSend(m.product.name)}
                >
                  {m.product.image && <img src={m.product.image} alt={m.product.name} />}
                  <div>
                    <strong>{m.product.name}</strong>
                    <div>SKU: {m.product.sku}</div>
                    {m.product.price && <div>Price: KES {m.product.price}</div>}
                    {m.product.description && <div>{m.product.description}</div>}
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}

        {loading && (
          <div className="bot" style={{ marginTop: 8 }}>
            <div
              style={{
                display: 'inline-block',
                background: '#f1f5f9',
                padding: 10,
                borderRadius: 8,
                fontStyle: 'italic',
                color: '#555',
              }}
            >
              Typing...
            </div>
          </div>
        )}
      </div>

      {suggestions && suggestions.length > 0 && (
        <div style={{ marginTop: 12 }}>
          <strong>Suggestions:</strong>
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 6 }}>
            {suggestions.map((s, idx) => (
              <button key={idx} onClick={() => handleSend(s)}>
                {s}
              </button>
            ))}
          </div>
        </div>
      )}

      <div className="inputRow">
        <input
          type="text"
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={e => e.key === 'Enter' && handleSend()}
          placeholder="Ask me about Lato products e.g. 'show milk'"
        />
        <button onClick={() => handleSend()}>Send</button>
      </div>
    </div>
  )
}
